package io.tornado.persistence;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="telegram_daily_reports")public class TelegramDailyReport{public enum Status{PENDING,SENT,FAILED}@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(unique=true)private LocalDate reportDate;private Instant periodStart;private Instant periodEnd;private Instant generatedAt;private Long telegramMessageId;@Enumerated(EnumType.STRING)@Column(length=16)private Status status;private int attempts;@Column(length=500)private String error;private Instant createdAt;private Instant updatedAt;protected TelegramDailyReport(){}public TelegramDailyReport(LocalDate date,Instant start,Instant end,Instant now){reportDate=date;periodStart=start;periodEnd=end;generatedAt=now;status=Status.PENDING;createdAt=now;updatedAt=now;}public void sent(long messageId){attempts++;telegramMessageId=messageId;status=Status.SENT;error=null;updatedAt=Instant.now();}public void failed(String message){attempts++;status=Status.FAILED;error=message==null?"Telegram delivery failed":message.substring(0,Math.min(500,message.length()));updatedAt=Instant.now();}public Long getId(){return id;}public LocalDate getReportDate(){return reportDate;}public Instant getPeriodStart(){return periodStart;}public Instant getPeriodEnd(){return periodEnd;}public Instant getGeneratedAt(){return generatedAt;}public Long getTelegramMessageId(){return telegramMessageId;}public Status getStatus(){return status;}public int getAttempts(){return attempts;}public String getError(){return error;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
